INSERT INTO public.site_settings (id, key, value, updated_at) VALUES ('9449d54e-7618-4228-a5e4-d2c2e47bd196', 'homepage_banner', '{"title": "Kalaasutra by Shubham Art", "subtitle": "Handcrafted customized artwork, LED signboards, and premium nameplates for your special ones.", "image_url": "hero_bg.jpg"}'::jsonb, now());
INSERT INTO public.site_settings (id, key, value, updated_at) VALUES ('12d170a4-b541-4e22-adba-5063e42f0f86', 'active_theme', '"premium"'::jsonb, now());
INSERT INTO public.site_settings (id, key, value, updated_at) VALUES ('452ebf17-221a-4ea1-8990-973b14d504c1', 'delivery_message', '"Express delivery all over India. Handcrafted sketches shipped within 7-9 business days."'::jsonb, now());
INSERT INTO public.site_settings (id, key, value, updated_at) VALUES ('93cd1d97-dc24-4a5d-962d-95b6c193e15e', 'announcement_bar', '"\ud83c\udf89 Flat 10% Off on Anniversary & Birthday Portraits! Use code FESTIVE10 at checkout."'::jsonb, now());
INSERT INTO public.site_settings (id, key, value, updated_at) VALUES ('76fcd1cb-a96d-4b4e-8119-b0250c960fcb', 'payment_instructions', '"Kindly scan the UPI QR code or pay to mobile number +91 8421949875 (Shubham Sutar). Share your order number and transaction screenshot on WhatsApp to activate your order."'::jsonb, now());
INSERT INTO public.site_settings (id, key, value, updated_at) VALUES ('38b4dded-d694-4a54-9c11-617cb8af72e9', 'faq', '[{"question": "How do I place a custom order?", "answer": "Choose your product, click \"Customize Preview\" to enter details (names, styles, reference images), and click \"Order via WhatsApp\". The website will generate a pre-filled WhatsApp message. Once you send it, our artist will confirm details and share payment options."}, {"question": "Can I get my portrait framed?", "answer": "Yes! We offer options for premium Black Classic frames or Warm Wooden frames for physical deliveries. You can also opt for unframed rolled sketches or a high-resolution digital copy."}, {"question": "How long does delivery take?", "answer": "Since each artwork is hand-drawn and customized with precision, creation takes 3-5 days. Shipping takes another 3-4 days. Total delivery time is approximately 7-9 business days across India."}, {"question": "What are the payment modes?", "answer": "We support payments via UPI (GPay, PhonePe, Paytm) and direct bank transfers. You will need to share the payment screenshot on WhatsApp to finalize your order."}]'::jsonb, now());
INSERT INTO public.offers (id, title, code, description, discount_type, discount_value, starts_at, ends_at, is_active, banner_image_url, applies_to, minimum_order_value, created_at, updated_at) VALUES ('3728e199-dcdf-4d92-973e-5c0a51c5d0dc', 'Festive Celebration Sale', 'FESTIVE10', 'Enjoy a flat 10% discount on all custom sketches and portrait orders.', 'percentage', 10.00, now(), now() + interval '90 days', true, 'festive_offer_banner.jpg', 'all_products', 499.00, now(), now());
INSERT INTO public.offers (id, title, code, description, discount_type, discount_value, starts_at, ends_at, is_active, banner_image_url, applies_to, minimum_order_value, created_at, updated_at) VALUES ('29460f6d-4fb3-4778-bddf-40e81903e861', 'Welcome First Order Discount', 'FIRST50', 'Get a flat ₹50 discount on your first order. Minimum purchase ₹299.', 'fixed_amount', 50.00, now(), now() + interval '365 days', true, 'welcome_offer_banner.jpg', 'all_products', 299.00, now(), now());
INSERT INTO public.testimonials (id, customer_name, message, rating, source, is_visible, display_order, created_at) VALUES ('29d85afd-c9e3-4b87-b78f-d817f6949c14', 'Aarav Mehta', 'Ordered an anniversary A3 sketch frame for my wife. The details were incredible and looked exactly like the reference photo. She loved it! Fast shipping too.', 5, 'whatsapp', true, 0, now());
INSERT INTO public.testimonials (id, customer_name, message, rating, source, is_visible, display_order, created_at) VALUES ('e1efd509-ca86-4400-b8e1-17b5c4945c6a', 'Priya Deshmukh', 'The Acrylic LED Nameplate is of premium quality. The light is bright and the calligraphy font is gorgeous. Highly recommended for home decor!', 5, 'instagram', true, 0, now());
INSERT INTO public.testimonials (id, customer_name, message, rating, source, is_visible, display_order, created_at) VALUES ('3d8b57b5-1159-4519-a5a6-bcea84be282b', 'Rohan Joshi', 'Got a metal keychain with my name. Excellent build quality, and it feels heavy and premium. Truly value for money.', 4, 'instagram', true, 0, now());
INSERT INTO public.testimonials (id, customer_name, message, rating, source, is_visible, display_order, created_at) VALUES ('5930c95e-0d93-4f9b-b5c7-71590637300d', 'Neha Shinde', 'Amazing customer support! They kept me updated during the sketch creation and took my feedback positively before shipping.', 5, 'website', true, 0, now());
